"""Compare four window predictors using one fixed, fully conditioned mask.

This diagnostic runs after the native GPU matrix. Group costs use only equally
weighted calibration-process means; target durations enter error reporting only.
It imports the matrix's independent reference, never the production estimator.
"""

from collections import defaultdict
import hashlib
import json
import math
from pathlib import Path
import statistics
import sys

ROOT = Path('<repository>')
BASE = Path('<experiment>/period4')
MODELS = ('batch_only', 'batch_epoch', 'batch_event', 'batch_event_epoch')
sys.path.insert(0, str(ROOT / 'tests'))
from native.finetune_event_window_matrix import _reference_windows


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False)


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def digest(value):
    return hashlib.sha256(value.encode()).hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def trace(run):
    return _reference_windows(run, epoch_context=True)


def key(row, model):
    data = json.loads(row['key'])
    if model == 'batch_only':
        return canonical(data['batches'])
    if model == 'batch_event_epoch':
        return row['key']
    fields = ('batches', 'epoch_context') if model == 'batch_epoch' else ('batches', 'context')
    return canonical({field: data[field] for field in fields})


def fit(runs, model):
    samples = []
    for run in runs:
        groups = defaultdict(list)
        for row in trace(run):
            if row['eligible']:
                groups[key(row, model)].append(row['seconds'])
        samples.append(groups)
    return samples


def predict(row, samples, model):
    group = key(row, model)
    if any(len(process.get(group, [])) < 2 for process in samples):
        raise ValueError(f'{model}: fewer than two samples per calibration process')
    return statistics.mean(statistics.mean(process[group]) for process in samples)


def comparison(rows, model):
    if not rows:
        raise ValueError('empty diagnostic subset')
    predicted = sum(row['predictions'][model] for row in rows)
    actual = sum(row['observed_seconds'] for row in rows)
    if not math.isfinite(actual) or actual <= 0:
        raise ValueError('diagnostic needs positive finite observed time')
    return {
        'optimizer_updates': len(rows),
        'optimizer_steps': [row['optimizer_step'] for row in rows],
        'predicted_seconds': predicted,
        'observed_seconds': actual,
        'absolute_percentage_error': abs(predicted - actual) / actual * 100,
        'signed_percentage_error': (predicted - actual) / actual * 100,
    }


def compare_models(rows):
    return {model: comparison(rows, model) for model in MODELS}


def event_collisions(runs):
    descriptions = {}
    processes = []
    for run in runs:
        groups = defaultdict(lambda: defaultdict(list))
        for row in trace(run):
            if row['eligible']:
                event_key = key(row, 'batch_event')
                position = canonical(json.loads(row['key'])['epoch_context'])
                descriptions[event_key] = json.loads(event_key)
                groups[event_key][position].append(row)
        processes.append(groups)
    evidence = []
    for event_key in sorted(descriptions):
        contexts = set().union(*(set(process.get(event_key, {})) for process in processes))
        if len(contexts) < 2:
            continue
        evidence.append({
            'batch_event_group_id': digest(event_key),
            'batch_event_descriptor': descriptions[event_key],
            'epoch_contexts': [json.loads(position) for position in sorted(contexts)],
            'calibration_runs': [
                {
                    'run_uuid': run['run_identity']['uuid'],
                    'positions': [
                        {'epoch_context': json.loads(position),
                         'optimizer_steps': [row['optimizer_step'] for row in rows],
                         'samples': len(rows), 'mean_seconds': statistics.mean(row['seconds'] for row in rows)}
                        for position, rows in sorted(process.get(event_key, {}).items())],
                }
                for run, process in zip(runs, processes)
            ],
        })
    return evidence


def run_diagnostic():
    result = {
        'schema_version': 'fakegpu.epoch_event_window_ablation.v1',
        'status': 'passed',
        'models': list(MODELS),
        'mask': 'Each process independently excludes global warmup and its first complete batch/event/epoch descriptor. The resulting mask is identical across all four predictors.',
        'aggregation': 'equal_weight_per_calibration_process_group_mean',
        'minimum_samples_per_group_per_calibration_run': 2,
        'script_sha256': sha(__file__),
        'reference_sha256': {
            str(path.relative_to(ROOT)): sha(path)
            for path in (ROOT / 'tests/native/finetune_event_matrix.py', ROOT / 'tests/native/finetune_event_window_matrix.py')
        },
        'frameworks': {},
        'limitations': [
            'This is an empirical replay diagnostic on recorded windows, not a fallback exposed by the periodic-event gate.',
            'All methods share the same retained calibration and target updates. Target durations do not determine calibration means or grouping policy.',
            'Changing event/epoch phase creates observed descriptor collisions, but does not isolate causes or control earlier events, device state, filesystem state, or system load.',
            'Every result is retained, including negative results and large subgroup errors. No measured speed improvement or total wall-time/VRAM forecast is claimed.',
        ],
    }
    for framework in ('llamafactory', 'axolotl'):
        directory = BASE / 'validation' / framework
        summary_path = directory / 'event-window-summary.json'
        summary = read(summary_path)
        if summary['status'] != 'completed' or not summary['sampling_plan']['epoch_context']:
            raise ValueError('fully conditioned native matrix has not completed')
        calibration_steps = summary['sampling_plan']['calibration_steps']
        matrix = read(directory / 'summary.json')
        paths = {role: Path(entry['report']) for role, entry in matrix['runs'].items()}
        reports = {role: read(path) for role, path in paths.items()}
        if len({report['run_identity']['uuid'] for report in reports.values()}) != len(reports):
            raise ValueError('calibration/holdout identities are not independent')
        calibrations = [reports[role] for role in ('calibration-1', 'calibration-2')]
        samples = {model: fit(calibrations, model) for model in MODELS}
        framework_result = {
            'matrix_summary_sha256': sha(summary_path),
            'source_reports': {role: {'path': str(path), 'sha256': sha(path)} for role, path in paths.items()},
            'calibration': {
                role: {'run_uuid': reports[role]['run_identity']['uuid'], 'eligible_optimizer_steps': [row['optimizer_step'] for row in trace(reports[role]) if row['eligible']]}
                for role in ('calibration-1', 'calibration-2')
            },
            'batch_event_collisions': event_collisions(calibrations),
            'holdouts': {},
        }
        if not framework_result['batch_event_collisions']:
            raise ValueError('this dephased acceptance matrix did not produce an event-only collision')
        for role in ('holdout-1', 'holdout-2'):
            target = reports[role]
            recorded = summary['holdout_comparisons'][role]['estimate']
            projected = {row['optimizer_step']: row for row in recorded['target_updates']}
            retained = []
            for row in trace(target):
                stored = projected[row['optimizer_step']]
                if (stored['eligible'] != row['eligible'] or stored['window_id'] != digest(row['key'])
                    or stored['immediately_after_event'] != row['immediately_after_event']
                    or stored['epoch_context'] != row['epoch_context']):
                    raise ValueError('independent descriptor/mask differs from production result')
                if not row['eligible']:
                    continue
                predicted = {model: predict(row, samples[model], model) for model in MODELS}
                if not math.isclose(predicted['batch_event_epoch'], stored['predicted_seconds']['expected'], rel_tol=1e-12, abs_tol=1e-12):
                    raise ValueError('independent combined prediction differs from production result')
                data = json.loads(row['key'])
                positions = data['epoch_context']['batch_microsteps']
                config = target['training_config']
                full = len(data['batches']) == config['gradient_accumulation_steps'] and all(batch['shape'][0] == config['micro_batch_size'] for batch in data['batches'])
                position_class = 'epoch_start' if positions[0] == 1 else ('later_full' if full else 'tail')
                retained.append({
                    'optimizer_step': row['optimizer_step'], 'window_id': digest(row['key']),
                    'batch_event_group_id': digest(key(row, 'batch_event')),
                    'epoch_context': data['epoch_context'], 'epoch_position_class': position_class,
                    'immediately_after_event': row['immediately_after_event'],
                    'observed_seconds': row['seconds'], 'predictions': predicted,
                })
            predicates = {
                'whole_trace': lambda row: True,
                'immediately_after_event': lambda row: row['immediately_after_event'],
                'not_immediately_after_event': lambda row: not row['immediately_after_event'],
                'after_calibration_suffix': lambda row: row['optimizer_step'] > calibration_steps,
                'suffix_immediately_after_event': lambda row: row['optimizer_step'] > calibration_steps and row['immediately_after_event'],
                'epoch_start': lambda row: row['epoch_position_class'] == 'epoch_start',
                'later_full': lambda row: row['epoch_position_class'] == 'later_full',
                'tail': lambda row: row['epoch_position_class'] == 'tail',
            }
            grouped = defaultdict(list)
            for row in retained:
                grouped[row['window_id']].append(row)
            partition_groups = [{'window_id': group, 'comparisons': compare_models(rows)} for group, rows in sorted(grouped.items())]
            framework_result['holdouts'][role] = {
                'subsets': {name: compare_models([row for row in retained if predicate(row)]) for name, predicate in predicates.items()},
                'combined_partition_groups': partition_groups,
                'maximum_combined_partition_group_ape': {
                    model: max(partition_groups, key=lambda entry: entry['comparisons'][model]['absolute_percentage_error'])
                    for model in MODELS
                },
                'target_updates': retained,
            }
        result['frameworks'][framework] = framework_result
    if 'torch' in sys.modules or any(name.startswith('fakegpu.') for name in sys.modules):
        raise ValueError('independent diagnostic imported production or training code')
    output = BASE / 'epoch-context-ablation.json'
    output.write_text(json.dumps(result, sort_keys=True, indent=2, allow_nan=False) + '\n')
    print(json.dumps({'status': result['status'], 'output': str(output), 'cases': 4}))
    for framework, data in result['frameworks'].items():
        print(framework, 'event-only descriptor collisions', len(data['batch_event_collisions']))
        for role, held in data['holdouts'].items():
            print(role, json.dumps({name: {model: values['absolute_percentage_error'] for model, values in comparisons.items()} for name, comparisons in held['subsets'].items()}))
            print('maxgroup', json.dumps({model: row['comparisons'][model]['absolute_percentage_error'] for model, row in held['maximum_combined_partition_group_ape'].items()}))


if __name__ == '__main__':
    run_diagnostic()

