"""Independent event/epoch-conditioned window replay audit, using report data only.

No FakeGPU production helpers are imported. Run after the GPU matrix exits.
"""
from collections import Counter, defaultdict
from copy import deepcopy
import hashlib
import json
import math
from pathlib import Path
import re
import statistics
import sys

ROOT = Path(__file__).resolve().parent
BATCH_FIELDS = (
    'shape','token_slots','attention_mask_kind','row_nonpadding_tokens',
    'nonpadding_tokens','padding_tokens','labels_present','labels_kind',
    'row_supervised_tokens','supervised_tokens','row_causal_supervised_tokens',
    'causal_supervised_tokens','position_ids_kind','position_reset_offsets',
)

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False)

def batch(value):
    return {field: value[field] for field in BATCH_FIELDS}

def sha(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()

def workload(event):
    raw = event['workload']
    if event['kind'] == 'evaluation':
        return {
            'dataset': {field: raw['dataset'][field] for field in ('content_sha256','num_samples')},
            'batches': [batch(value) for value in raw['batches']],
            'consumed_content_sha256': raw['consumed_content_sha256'],
            **{field:raw[field] for field in ('prediction_loss_only','predict_with_generate','compute_metrics','eval_batch_size','dataloader_drop_last')},
        }
    return {
        'save_only_model': raw['save_only_model'], 'artifact_kind': raw['artifact_kind'],
        'file_layout': sorted(re.sub(r'(^|/)checkpoint-\d+(/|$)', r'\1checkpoint-N\2', file['path']) for file in raw['files']),
    }

def root_descriptors(events):
    children = defaultdict(list)
    for event in events:
        children[event['parent_event_id']].append(event)
    seen = set()
    result = {}
    for root in children[None]:
        indices = {root['event_id']:0}
        nested = []
        def visit(parent):
            for child in children[parent['event_id']]:
                indices[child['event_id']] = len(indices)
                nested.append({'kind':child['kind'],'operation':child['operation'],'parent_operation_index':indices[parent['event_id']]})
                visit(child)
        visit(root)
        descriptor = {'kind':root['kind'],'operation':root['operation'],'inside_train':root['inside_train'],'workload':workload(root),'nested_operations':nested}
        base = canonical(descriptor)
        if root['optimizer_step'] == 0:
            phase = 'initial'
        elif not root['inside_train']:
            phase = 'final'
        else:
            phase = 'repeated' if base in seen else 'first'
            seen.add(base)
        result[root['event_id']] = {**descriptor,'phase':phase}
    return result

def samples(path):
    report = json.loads(path.read_text())
    observation = report['observation']
    events = observation['phase_events']
    roots = [event for event in events if event['parent_event_id'] is None and event['inside_train']]
    descriptors = root_descriptors(events)
    boundaries = defaultdict(list)
    for root in roots:
        boundaries[root['optimizer_step']].append(root)
    latest = {}
    seen = set()
    trace = []
    groups = defaultdict(list)
    counts = Counter()
    for update in observation['updates']:
        step = update['optimizer_step']
        predecessors = boundaries[step - 1]
        assert update['preceding_event_ids'] == [event['event_id'] for event in predecessors]
        if predecessors:
            for event in predecessors:
                latest[event['kind']] = (step - 1, [descriptors[item['event_id']] for item in predecessors])
        context = {}
        for kind in ('evaluation','checkpoint'):
            if kind not in latest:
                context[kind] = None
            else:
                boundary, bundle = latest[kind]
                context[kind] = {'events':deepcopy(bundle),'optimizer_updates_since_boundary':step-boundary-1}
        key = {'batches':[batch(item) for item in update['batches']],'context':context, 'epoch_context':{'batch_microsteps':[item['epoch_microstep'] for item in update['batches']]}}
        group_id = sha(key)
        first = group_id not in seen
        seen.add(group_id)
        reasons=[]
        if update['warmup']:reasons.append('global_warmup')
        if first:reasons.append('first_window_occurrence')
        eligible=not reasons
        counts['warmup'] += update['warmup']
        counts['first'] += first
        counts['excluded'] += not eligible
        record={'optimizer_step':step,'window_id':group_id,'eligible':eligible,'excluded_reasons':reasons,'immediately_after_event':bool(predecessors),'observed_seconds':update['seconds'],'key':key}
        trace.append(record)
        if eligible:groups[group_id].append(record)
    return {'raw':report,'trace':trace,'groups':dict(groups),'counts':dict(counts),'path':path}

def independent_prediction(calibrations, target):
    reference={}
    for group_id,records in target['groups'].items():
        process=[]
        for calibration in calibrations:
            samples=calibration['groups'].get(group_id,[])
            assert len(samples)>=2,(group_id,calibration['path'],len(samples))
            process.append(statistics.mean(item['observed_seconds'] for item in samples))
        reference[group_id]={'min':min(process),'expected':statistics.mean(process),'max':max(process)}
    predicted=[{'optimizer_step':record['optimizer_step'],'expected':reference[record['window_id']]['expected'],'actual':record['observed_seconds'],'epoch_context':record['key']['epoch_context'],'immediately_after_event':record['immediately_after_event']} for record in target['trace'] if record['eligible']]
    return reference,predicted

def check_close(actual, expected, label):
    assert math.isclose(actual,expected,rel_tol=1e-12,abs_tol=1e-10),(label,actual,expected)

def audit_prediction(path, output, calibrations, target):
    assert output['scope'] == 'recorded_event_epoch_conditioned_optimizer_window_replay'
    assert output['sampling_policy']['epoch_context'] == 'recorded_epoch_microsteps_per_batch'
    assert output['sampling_policy']['exclude_first_context_window_occurrence'] is True
    reference,predicted=independent_prediction(calibrations,target)
    assert len(reference) == 12
    assert len(target['trace']) == 89 and len(predicted) == 69
    for run in calibrations:
        assert len(run['trace']) == 68 and sum(len(rows) for rows in run['groups'].values()) == 48
        assert sorted(len(rows) for rows in run['groups'].values()) == [4] * 12
    assert len(output['target_updates']) == len(target['trace'])
    for observed,expected in zip(output['target_updates'],target['trace']):
        for field in ('optimizer_step','window_id','eligible','excluded_reasons','immediately_after_event'):
            assert observed[field]==expected[field],(path,field,observed[field],expected[field])
        assert observed['epoch_context'] == expected['key']['epoch_context']
        if expected['eligible']:
            for field,value in reference[expected['window_id']].items():
                check_close(observed['predicted_seconds'][field],value,(path,expected['optimizer_step'],field))
        else:
            assert observed['predicted_seconds'] is None
    actual_groups={group['window_id']:group for group in output['window_groups']}
    assert set(actual_groups)==set(reference)
    for group_id,estimate in reference.items():
        records=target['groups'][group_id]
        observed=actual_groups[group_id]
        assert observed['context']==records[0]['key']['context']
        assert observed['batches']==records[0]['key']['batches']
        assert observed['epoch_context']==records[0]['key']['epoch_context']
        assert observed['target_optimizer_steps']==[row['optimizer_step'] for row in records]
        for field,value in estimate.items():check_close(observed['seconds_per_window'][field],value,(group_id,field))
        for sampled,calibration in zip(observed['calibration_runs'],calibrations):
            actual=calibration['groups'][group_id]
            assert sampled['optimizer_steps']==[row['optimizer_step'] for row in actual]
            assert sampled['samples']==len(actual)
            check_close(sampled['seconds']['mean'],statistics.mean(row['observed_seconds'] for row in actual),group_id)
    subsets={}
    cal_end=max(len(run['trace']) for run in calibrations)
    selections = [
        ('all_eligible',predicted),
        ('after_calibration_length',[row for row in predicted if row['optimizer_step']>cal_end]),
        ('immediately_after_event',[row for row in predicted if row['immediately_after_event']]),
        ('after_calibration_length_immediately_after_event',[row for row in predicted if row['immediately_after_event'] and row['optimizer_step']>cal_end]),
    ]
    epoch_subsets={
        'epoch_start':[row for row in predicted if row['epoch_context']['batch_microsteps'][0] == 1],
        'later_full_windows':[row for row in predicted if len(row['epoch_context']['batch_microsteps']) > 1 and row['epoch_context']['batch_microsteps'][0] > 1],
        'epoch_tail':[row for row in predicted if len(row['epoch_context']['batch_microsteps']) == 1],
    }
    for name,rows in epoch_subsets.items():
        assert len(rows) == 23
        selections.extend([(name,rows),('after_calibration_length_'+name,[row for row in rows if row['optimizer_step']>cal_end])])
    for name,selected in selections:
        assert selected,name
        estimated=sum(row['expected'] for row in selected)
        actual=sum(row['actual'] for row in selected)
        subsets[name]={'updates':len(selected),'optimizer_steps':[row['optimizer_step'] for row in selected],'predicted_seconds':estimated,'actual_seconds':actual,'absolute_percentage_error':abs(estimated-actual)/actual*100}
    check_close(output['timing']['steady_optimizer_window_seconds']['expected'],subsets['all_eligible']['predicted_seconds'],'overall prediction')
    check_close(output['timing']['comparison']['actual'],subsets['all_eligible']['actual_seconds'],'overall actual')
    context_positions=defaultdict(set)
    event_batch_positions=defaultdict(set)
    for record in target['trace']:
        if record['eligible']:
            positions=tuple(record['key']['epoch_context']['batch_microsteps'])
            context_positions[canonical(record['key']['context'])].add(positions)
            event_batch_positions[canonical({k:v for k,v in record['key'].items() if k!='epoch_context'})].add(positions)
    collisions=[{'event_batch_key_sha256':hashlib.sha256(key.encode()).hexdigest(), 'batch_microsteps':[list(p) for p in sorted(positions)]} for key,positions in sorted(event_batch_positions.items()) if len(positions)>1]
    assert collisions and all(row['batch_microsteps']==[[1,2],[3,4]] for row in collisions)
    # Controlled ablation: use exactly the SAME retained calibration and target
    # updates, dropping only epoch position from the key. This is not the legacy
    # API's differing first-occurrence policy, and does not feed target times to fit.
    merged_calibrations=[]
    for run in calibrations:
        merged=defaultdict(list)
        for row in run['trace']:
            if row['eligible']:
                key=canonical({k:v for k,v in row['key'].items() if k!='epoch_context'})
                merged[key].append(row['observed_seconds'])
        merged_calibrations.append(merged)
    ablation_predictions={}
    for row in target['trace']:
        if row['eligible']:
            key=canonical({k:v for k,v in row['key'].items() if k!='epoch_context'})
            assert all(len(run[key])>=2 for run in merged_calibrations)
            ablation_predictions[row['optimizer_step']]=statistics.mean(statistics.mean(run[key]) for run in merged_calibrations)
    ablation={}
    for name,selected in selections:
        predicted_merged=sum(ablation_predictions[row['optimizer_step']] for row in selected)
        actual=sum(row['actual'] for row in selected)
        ablation[name]={'updates':len(selected),'predicted_seconds':predicted_merged,'actual_seconds':actual,'absolute_percentage_error':abs(predicted_merged-actual)/actual*100}
    return {'event_context_epoch_positions':[{'context':json.loads(key),'batch_microsteps':[list(p) for p in sorted(positions)]} for key,positions in sorted(context_positions.items())], 'event_only_key_epoch_collisions':collisions, 'controlled_drop_epoch_ablation':{'method':'Identical eligible calibration and target updates; only epoch_context removed from grouping. Equal weight for each process mean. Target durations are comparison-only.', 'subsets':ablation}, 'prediction_path':str(path.relative_to(ROOT)),'prediction_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'target_exclusions':target['counts'],'calibration_group_sample_counts':[sorted(len(run['groups'][group]) for group in reference) for run in calibrations],'groups':len(reference),'subsets':subsets,'passed':True}

def main():
    results=[]
    for framework in ('llamafactory','axolotl'):
        directory=ROOT/'validation'/framework
        calibrations=[samples(directory/name/'report.json') for name in ('calibration-1','calibration-2')]
        targets={name:samples(directory/name/'report.json') for name in ('holdout-1','holdout-2')}
        path=directory/'event-window-summary.json'
        predictions=json.loads(path.read_text())['holdout_comparisons']
        for name,target in targets.items():
            result=audit_prediction(path,predictions[name]['estimate'],calibrations,target)
            result.update(framework=framework,holdout=name)
            results.append(result)
    output=ROOT/'independent-context-audit.json'
    output.write_text(json.dumps({'all_passed':True,'holdouts':results,'method':'Independent report-only reconstruction of root semantics, complete per-kind latest boundary bundles, exact window-event-epoch-context IDs, exclusions and equally weighted calibration process means. No production inspector or estimator helpers imported.'},indent=2)+'\n')
    print(json.dumps({'all_passed':True,'holdouts':len(results),'output':str(output)}))

if __name__=='__main__':main()

