    },
)
gc_collect_steps: int | None = Field(
    default=None,
    json_schema_extra={
        "description": "Steps between Python `gc.collect()` calls. -1 runs on epoch end and before evals only; None disables."
    },
)

gc_collect_steps = self.cfg.gc_collect_steps or self.cfg.gc_steps
if gc_collect_steps:
    callbacks.append(GCCallback(gc_collect_steps=gc_collect_steps))

class GCCallback(TrainerCallback):
    """Runs ``gc.collect()`` + ``torch.cuda.empty_cache()`` on
    ``gc_collect_steps`` intervals and on eval/save/epoch boundaries that
    the Trainer's native ``torch_empty_cache_steps`` doesn't cover. The two
    settings are complementary; overlapping intervals just double-clear.
    """

    def __init__(self, gc_collect_steps: int | None = -1, gc_steps: int | None = None):
        if gc_steps is not None and gc_collect_steps in (-1, None):
            gc_collect_steps = gc_steps
        self.gc_collect_steps: int = gc_collect_steps or -1
        self.next_gc_on_begin_step: int = -1

    def _gc(self):
        gc.collect()
        torch.cuda.empty_cache()

    def on_train_begin(
        self,
        args,
        state,
        control,
        **kwargs,
    ):
        self._gc()

    def on_step_begin(
        self,
        args,
        state,
        control,
        **kwargs,
    ):
        if self.next_gc_on_begin_step == state.global_step or state.global_step == 0:
            self._gc()

    def on_step_end(
        self,
        args,
        state,
        control,
        **kwargs,
    ):
        if control.should_evaluate:
            # automatically GC before evals so the eval memory spike from the CEL doesn't OOM the trainer
            self._gc()
            # also GC on the start of the next step after the eval
            self.next_gc_on_begin_step = state.global_step + 1
        elif (
            self.gc_collect_steps > 0 and state.global_step % self.gc_collect_steps == 0
        ):
            self._gc()
        elif (
            args.save_strategy == SaveStrategy.STEPS
            and state.save_steps > 0
            and state.global_step % state.save_steps == 0
        ):
            # gc on save steps in case anything is loaded to CPU RAM like offloaded tensors
            self._gc()
        elif state.global_step >= state.max_steps:
            if args.save_strategy == SaveStrategy.STEPS:
                # gc on save steps in case anything is loaded to CPU RAM like offloaded tensors
                self._gc()

    def on_epoch_end(
        self,
        args,
        state,
        control,
        **kwargs,
    ):
        self._gc()

def get_batch_samples(
    self, epoch_iterator: Iterator, num_batches: int, device: torch.device
) -> tuple[list, torch.Tensor | int | None]:
    """
    Collects a specified number of batches from the epoch iterator and optionally counts the number of items in the batches to properly scale the loss.
    """
    batch_samples = []

    for _ in range(num_batches):
        try:
            batch_samples.append(next(epoch_iterator))
        except StopIteration:
            break

    num_items_in_batch = self._get_num_items_in_batch(batch_samples, device)
    return batch_samples, num_items_in_batch

    # We iterate one batch ahead to check when we are at the end
    try:
        current_batch = next(dataloader_iter)
    except StopIteration:
        self.end()
        return

    batch_index = 0
    while True:
        try:
            # But we still move it to the device so it is done before `StopIteration` is reached
            if self.device is not None:
                current_batch = send_to_device(current_batch, self.device, non_blocking=self._non_blocking)
            self._update_state_dict()
            next_batch = next(dataloader_iter)
            if batch_index >= self.skip_batches:
                yield current_batch
            batch_index += 1
            current_batch = next_batch
        except StopIteration:
            self.end_of_dataloader = True
            self._update_state_dict()
            if batch_index >= self.skip_batches:
                yield current_batch
            break

    self.iteration += 1
    self.end()

def __reduce__(self):
    """
    Define the `__reduce__` method to ensure a `DataLoaderShard` can be pickled and unpickled. This needs to be
    explicitly defined since default pickling behavior is broken by `DataLoaderAdapter` messing with its
    `__class__` member.
    """
    args = super().__reduce__()
    return (DataLoaderShard, *args[1:])

def set_epoch(self, epoch: int):
    # In case it is manually passed in, the user can set it to what they like
    if self.iteration != epoch:
        self.iteration = epoch

def __iter__(self) -> _BaseDataLoaderIter:
    # When using a single worker the returned iterator should be
    # created every time to avoid resetting its state
    # However, in the case of a multiple workers iterator
    # the iterator is only created once in the lifetime of the
    # DataLoader object so that workers can be reused
    if self.persistent_workers and self.num_workers > 0:
        if self._iterator is None:
            self._iterator = self._get_iterator()
        else:
            self._iterator._reset(self)
        return self._iterator
    else:
        return self._get_iterator()

@property
def _auto_collation(self):
    return self.batch_sampler is not None

    return batch_samples(*args, **kwargs)

def measured_step(*args, **kwargs):
    inputs = kwargs.get("inputs", args[1] if len(args) > 1 else None)
    # Wait for preceding training work before starting the metadata timer:
    # a host copy must not subtract unfinished GPU compute from the sample.
    self.torch.cuda.synchronize()
    metadata_started = time.perf_counter()
    try:
        batch = describe_batch(inputs)
    except ValueError as exc:
        raise RuntimeError(f"invalid native text microbatch: {exc}") from exc
    self.torch.cuda.synchronize()
